@dataclass
class Color:
    r: float
    g: float
    b: float
    a: float = 1.0
    def clipped(self):
        return Color(clamp(self.r), clamp(self.g), clamp(self.b), clamp(self.a))
    def rgb8(self):
        c=self.clipped(); return (to8(c.r), to8(c.g), to8(c.b))
    def hex(self):
        r,g,b=self.rgb8();
        if self.a < 0.9995:
            return f"#{r:02x}{g:02x}{b:02x}{to8(clamp(self.a)):02x}"
        return f"#{r:02x}{g:02x}{b:02x}"


def clamp(x, lo=0.0, hi=1.0):
    try: x=float(x)
    except Exception: return lo
    return lo if x<lo else hi if x>hi else x

def to8(x): return int(math.floor(clamp(x)*255.0 + 0.5))
def fmt_f(x, n):
    # avoid ugly negative zero for most human formats
    if abs(x) < 0.5*10**(-n): x = 0.0
    return f"{x:.{n}f}"
def round_int(x): return int(math.floor(x+0.5)) if x>=0 else int(math.ceil(x-0.5))
def pct_token(s):
    s=s.strip()
    if s.endswith('%'): return float(s[:-1])/100.0
    return float(s)
def chan_token(s):
    s=s.strip()
    if s.endswith('%'): return clamp(float(s[:-1])/100.0)
    return clamp(float(s)/255.0)
def alpha_token(s):
    s=s.strip()
    if s.endswith('%'): return clamp(float(s[:-1])/100.0)
    return clamp(float(s))
def parse_angle(s):
    s=s.strip().lower()
    mult=1.0
    if s.endswith('turn'):
        mult=360.0; s=s[:-4]
    elif s.endswith('grad'):
        mult=0.9; s=s[:-4]
    elif s.endswith('rad'):
        mult=180.0/math.pi; s=s[:-3]
    elif s.endswith('deg'):
        mult=1.0; s=s[:-3]
    return (float(s)*mult) % 360.0

def srgb_to_linear(c): return c/12.92 if c <= 0.04045 else ((c+0.055)/1.055)**2.4
def linear_to_srgb(c): return 12.92*c if c <= 0.0031308 else 1.055*(max(c,0.0)**(1/2.4))-0.055

def rgb_to_xyz(c):
    r,g,b=[srgb_to_linear(x) for x in (c.r,c.g,c.b)]
    x = 0.4124564*r + 0.3575761*g + 0.1804375*b
    y = 0.2126729*r + 0.7151522*g + 0.0721750*b
    z = 0.0193339*r + 0.1191920*g + 0.9503041*b
    return x,y,z

def xyz_to_rgb(x,y,z,a=1.0):
    r =  3.2404542*x -1.5371385*y -0.4985314*z
    g = -0.9692660*x +1.8760108*y +0.0415560*z
    b =  0.0556434*x -0.2040259*y +1.0572252*z
    return Color(linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(b), a).clipped()

def rgb_to_lab(c):
    x,y,z=rgb_to_xyz(c); Xn,Yn,Zn=0.95047,1.0,1.08883
    def f(t): return t**(1/3) if t > 216/24389 else (24389/27*t + 16)/116
    fx,fy,fz=f(x/Xn),f(y/Yn),f(z/Zn)
    return 116*fy-16, 500*(fx-fy), 200*(fy-fz)

def lab_to_rgb(L,a,b,alpha=1.0):
    Xn,Yn,Zn=0.95047,1.0,1.08883
    fy=(L+16)/116; fx=fy+a/500; fz=fy-b/200
    def finv(t): return t**3 if t**3 > 216/24389 else (116*t-16)/(24389/27)
    return xyz_to_rgb(Xn*finv(fx), Yn*finv(fy), Zn*finv(fz), alpha)

def lab_to_lch(L,a,b):
    C=math.hypot(a,b); h=(math.degrees(math.atan2(b,a))%360.0) if C!=0 else 0.0
    return L,C,h

def lch_to_lab(L,C,h):
    rad=math.radians(h); return L, C*math.cos(rad), C*math.sin(rad)

def rgb_to_oklab(c):
    r,g,b=[srgb_to_linear(x) for x in (c.r,c.g,c.b)]
    l=0.4122214708*r + 0.5363325363*g + 0.0514459929*b
    m=0.2119034982*r + 0.6806995451*g + 0.1073969566*b
    s=0.0883024619*r + 0.2817188376*g + 0.6299787005*b
    l_,m_,s_=math.copysign(abs(l)**(1/3),l),math.copysign(abs(m)**(1/3),m),math.copysign(abs(s)**(1/3),s)
    L=0.2104542553*l_ + 0.7936177850*m_ - 0.0040720468*s_
    A=1.9779984951*l_ - 2.4285922050*m_ + 0.4505937099*s_
    B=0.0259040371*l_ + 0.7827717662*m_ - 0.8086757660*s_
    return L,A,B

def oklab_to_rgb(L,A,B,alpha=1.0):
    l_ = L + 0.3963377774*A + 0.2158037573*B
    m_ = L - 0.1055613458*A - 0.0638541728*B
    s_ = L - 0.0894841775*A - 1.2914855480*B
    l,m,s=l_**3,m_**3,s_**3
    r = +4.0767416621*l - 3.3077115913*m + 0.2309699292*s
    g = -1.2684380046*l + 2.6097574011*m - 0.3413193965*s
    b = -0.0041960863*l - 0.7034186147*m + 1.7076147010*s
    return Color(linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(b), alpha).clipped()

def rgb_to_hsl(c):
    r,g,b=c.r,c.g,c.b; mx=max(r,g,b); mn=min(r,g,b); d=mx-mn; l=(mx+mn)/2
    if d == 0: return 0.0,0.0,l
    s=d/(1-abs(2*l-1))
    if mx==r: h=((g-b)/d)%6
    elif mx==g: h=(b-r)/d+2
    else: h=(r-g)/d+4
    return (60*h)%360, s, l

def hsl_to_rgb(h,s,l,a=1.0):
    h=(h%360)/30.0; s=clamp(s); l=clamp(l)
    C=(1-abs(2*l-1))*s; X=C*(1-abs(h%2-1)); m=l-C/2
    if h<1: r,g,b=C,X,0
    elif h<2: r,g,b=X,C,0
    elif h<3: r,g,b=0,C,X
    elif h<4: r,g,b=0,X,C
    elif h<5: r,g,b=X,0,C
    else: r,g,b=C,0,X
    return Color(r+m,g+m,b+m,a).clipped()

def rgb_to_hsv(c):
    r,g,b=c.r,c.g,c.b; mx=max(r,g,b); mn=min(r,g,b); d=mx-mn
    if d==0: h=0
    elif mx==r: h=60*(((g-b)/d)%6)
    elif mx==g: h=60*((b-r)/d+2)
    else: h=60*((r-g)/d+4)
    s=0 if mx==0 else d/mx
    return h,s,mx

def hsv_to_rgb(h,s,v,a=1.0):
    h=(h%360)/60; s=clamp(s); v=clamp(v); C=v*s; X=C*(1-abs(h%2-1)); m=v-C
    if h<1: r,g,b=C,X,0
    elif h<2: r,g,b=X,C,0
    elif h<3: r,g,b=0,C,X
    elif h<4: r,g,b=0,X,C
    elif h<5: r,g,b=X,0,C
    else: r,g,b=C,0,X
    return Color(r+m,g+m,b+m,a).clipped()

def rel_luminance(c):
    return 0.2126*srgb_to_linear(c.r)+0.7152*srgb_to_linear(c.g)+0.0722*srgb_to_linear(c.b)
def brightness(c): return 0.299*c.r + 0.587*c.g + 0.114*c.b

def split_args_inside(s):
    return [p.strip() for p in re.split(r'\s*,\s*|\s+', s.strip()) if p.strip()!='']

def parse_color(text):
    original=text; s=text.strip(); low=s.lower().replace(' ','')
    if low in CSS:
        h=CSS[low]; return parse_color(h)
    m=re.fullmatch(r'#?([0-9a-fA-F]{3}|[0-9a-fA-F]{4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})', s)
    if m:
        hx=m.group(1)
        if len(hx) in (3,4): hx=''.join(ch*2 for ch in hx)
        r=int(hx[0:2],16)/255; g=int(hx[2:4],16)/255; b=int(hx[4:6],16)/255; a=1.0
        if len(hx)==8: a=int(hx[6:8],16)/255
        return Color(r,g,b,a)
    m=re.fullmatch(r'rgba?\((.*)\)', s, re.I)
    if m:
        ps=split_args_inside(m.group(1));
        if len(ps) in (3,4): return Color(chan_token(ps[0]), chan_token(ps[1]), chan_token(ps[2]), alpha_token(ps[3]) if len(ps)==4 else 1.0)
    m=re.fullmatch(r'([+-]?\d+(?:\.\d+)?%?)\s*,\s*([+-]?\d+(?:\.\d+)?%?)\s*,\s*([+-]?\d+(?:\.\d+)?%?)', s)
    if m:
        return Color(chan_token(m.group(1)),chan_token(m.group(2)),chan_token(m.group(3)),1.0)
    m=re.fullmatch(r'hsla?\((.*)\)', s, re.I)
    if m:
        ps=split_args_inside(m.group(1));
        if len(ps) in (3,4): return hsl_to_rgb(parse_angle(ps[0]), pct_token(ps[1]), pct_token(ps[2]), alpha_token(ps[3]) if len(ps)==4 else 1.0)
    m=re.fullmatch(r'hsva?\((.*)\)', s, re.I)
    if m:
        ps=split_args_inside(m.group(1));
        if len(ps) in (3,4): return hsv_to_rgb(parse_angle(ps[0]), pct_token(ps[1]), pct_token(ps[2]), alpha_token(ps[3]) if len(ps)==4 else 1.0)
    m=re.fullmatch(r'gray\((.*)\)', s, re.I)
    if m:
        try:
            v=pct_token(m.group(1).strip())
            if v < 0: raise ValueError
            return Color(clamp(v),clamp(v),clamp(v),1.0)
        except Exception: pass
    for nm,func in [('lab',None),('lch',None),('oklab',None),('oklch',None)]:
        m=re.fullmatch(nm+r'\((.*)\)', s, re.I)
        if m:
            ps=split_args_inside(m.group(1));
            try:
                if nm=='lab' and len(ps) in (3,4): return lab_to_rgb(float(ps[0]),float(ps[1]),float(ps[2]), alpha_token(ps[3]) if len(ps)==4 else 1.0)
                if nm=='lch' and len(ps) in (3,4):
                    L,A,B=lch_to_lab(float(ps[0]),float(ps[1]),parse_angle(ps[2])); return lab_to_rgb(L,A,B, alpha_token(ps[3]) if len(ps)==4 else 1.0)
                if nm=='oklab' and len(ps) in (3,4): return oklab_to_rgb(float(ps[0]),float(ps[1]),float(ps[2]), alpha_token(ps[3]) if len(ps)==4 else 1.0)
                if nm=='oklch' and len(ps) in (3,4):
                    L=float(ps[0]); C=float(ps[1]); h=parse_angle(ps[2]); return oklab_to_rgb(L,C*math.cos(math.radians(h)),C*math.sin(math.radians(h)), alpha_token(ps[3]) if len(ps)==4 else 1.0)
            except Exception: pass
    raise ValueError(f"Could not parse color '{original}'")

FORMATS = 'rgb rgb-float rgb-r rgb-g rgb-b hex hsl hsl-hue hsl-saturation hsl-lightness hsv hsv-hue hsv-saturation hsv-value lch lch-lightness lch-chroma lch-hue oklch oklch-lightness oklch-chroma oklch-hue lab lab-a lab-b oklab oklab-l oklab-a oklab-b luminance brightness ansi-8bit ansi-24bit ansi-8bit-value ansi-8bit-escapecode ansi-24bit-escapecode cmyk name'.split()

def fmt_alpha(a):
    return f"{a:.3f}".rstrip('0').rstrip('.')

def fmt_hsl(c, spaces=True, compact=False):
    h,s,l=rgb_to_hsl(c); sep=', ' if spaces else ','
    fn='hsla' if c.a < 0.9995 else 'hsl'
    base=f"{fn}({round_int(h)%360}{sep}{s*100:.1f}%{sep}{l*100:.1f}%"
    if c.a < 0.9995: base += f"{sep}{fmt_alpha(c.a)}"
    return base+")"

def fmt_hsv(c, spaces=True):
    h,s,v=rgb_to_hsv(c); sep=', ' if spaces else ','; fn='hsva' if c.a<0.9995 else 'hsv'
    base=f"{fn}({round_int(h)%360}{sep}{s*100:.1f}%{sep}{v*100:.1f}%"
    if c.a<0.9995: base += f"{sep}{fmt_alpha(c.a)}"
    return base+")"

def nearest_ansi8(c):
    # xterm palette, choose nearest in RGB Euclidean. This matches common pastel outputs.
    r,g,b=c.rgb8(); best=0; bd=10**9
    def pal(i):
        base=[(0,0,0),(128,0,0),(0,128,0),(128,128,0),(0,0,128),(128,0,128),(0,128,128),(192,192,192),(128,128,128),(255,0,0),(0,255,0),(255,255,0),(0,0,255),(255,0,255),(0,255,255),(255,255,255)]
        if i<16: return base[i]
        if i<232:
            j=i-16; rr=j//36; gg=(j//6)%6; bb=j%6; vals=[0,95,135,175,215,255]; return vals[rr],vals[gg],vals[bb]
        v=8+(i-232)*10; return v,v,v
    for i in range(16,256):
        pr,pg,pb=pal(i); d=(r-pr)**2+(g-pg)**2+(b-pb)**2
        if d<bd: bd=d; best=i
    return best

def format_color(c, typ):
    r,g,b=c.rgb8()
    if typ=='hex': return c.hex()
    if typ=='rgb':
        return (f"rgba({r}, {g}, {b}, {fmt_alpha(c.a)})" if c.a<0.9995 else f"rgb({r}, {g}, {b})")
    if typ=='rgb-float':
        return (f"rgba({c.r:.3f}, {c.g:.3f}, {c.b:.3f}, {fmt_alpha(c.a)})" if c.a<0.9995 else f"rgb({c.r:.3f}, {c.g:.3f}, {c.b:.3f})")
    if typ=='rgb-r': return str(r)
    if typ=='rgb-g': return str(g)
    if typ=='rgb-b': return str(b)
    if typ=='hsl': return fmt_hsl(c, True)
    if typ=='hsl-hue': return str(round_int(rgb_to_hsl(c)[0])%360)
    if typ=='hsl-saturation': return f"{rgb_to_hsl(c)[1]:.4f}"
    if typ=='hsl-lightness': return f"{rgb_to_hsl(c)[2]:.4f}"
    if typ=='hsv': return fmt_hsv(c, True)
    if typ=='hsv-hue': return str(round_int(rgb_to_hsv(c)[0])%360)
    if typ=='hsv-saturation': return f"{rgb_to_hsv(c)[1]:.4f}"
    if typ=='hsv-value': return f"{rgb_to_hsv(c)[2]:.4f}"
    if typ=='lab':
        L,A,B=rgb_to_lab(c); s=f"Lab({round_int(L)}, {round_int(A)}, {round_int(B)}"; return s+(f", {fmt_alpha(c.a)})" if c.a<0.9995 else ")")
    if typ=='lab-a': return f"{rgb_to_lab(c)[1]:.2f}"
    if typ=='lab-b': return f"{rgb_to_lab(c)[2]:.2f}"
    if typ=='lch':
        L,A,B=rgb_to_lab(c); L,C,h=lab_to_lch(L,A,B); s=f"LCh({round_int(L)}, {round_int(C)}, {round_int(h)%360}"; return s+(f", {fmt_alpha(c.a)})" if c.a<0.9995 else ")")
    if typ=='lch-lightness': return f"{rgb_to_lab(c)[0]:.2f}"
    if typ=='lch-chroma':
        L,A,B=rgb_to_lab(c); return f"{math.hypot(A,B):.2f}"
    if typ=='lch-hue':
        L,A,B=rgb_to_lab(c); return f"{lab_to_lch(L,A,B)[2]:.2f}"
    if typ=='oklab':
        L,A,B=rgb_to_oklab(c); s=f"OkLab({L:.4f}, {A:.4f}, {B:.4f}"; return s+(f", {fmt_alpha(c.a)})" if c.a<0.9995 else ")")
    if typ=='oklab-l': return f"{rgb_to_oklab(c)[0]:.4f}"
    if typ=='oklab-a': return f"{rgb_to_oklab(c)[1]:.4f}"
    if typ=='oklab-b': return f"{rgb_to_oklab(c)[2]:.4f}"
    if typ=='oklch':
        L,A,B=rgb_to_oklab(c); C=math.hypot(A,B); h=(math.degrees(math.atan2(B,A))%360) if C!=0 else 0.0; s=f"OkLCh({L:.4f}, {C:.4f}, {h:.4f}"; return s+(f", {fmt_alpha(c.a)})" if c.a<0.9995 else ")")
    if typ=='oklch-lightness': return f"{rgb_to_oklab(c)[0]:.4f}"
    if typ=='oklch-chroma':
        L,A,B=rgb_to_oklab(c); return f"{math.hypot(A,B):.4f}"
    if typ=='oklch-hue':
        L,A,B=rgb_to_oklab(c); C=math.hypot(A,B); h=(math.degrees(math.atan2(B,A))%360) if C!=0 else 0.0; return f"{h:.4f}"
    if typ=='luminance': return f"{rel_luminance(c):.3f}"
    if typ=='brightness': return f"{brightness(c):.3f}"
    if typ=='ansi-8bit-value': return str(nearest_ansi8(c))
    if typ=='ansi-8bit': return f"\\x1b[38;5;{nearest_ansi8(c)}m"
    if typ=='ansi-24bit': return f"\\x1b[38;2;{r};{g};{b}m"
    if typ=='ansi-8bit-escapecode': return f"\x1b[38;5;{nearest_ansi8(c)}m"
    if typ=='ansi-24bit-escapecode': return f"\x1b[38;2;{r};{g};{b}m"
    if typ=='cmyk':
        if max(c.r,c.g,c.b)==0: C=M=Y=0; K=1
        else:
            K=1-max(c.r,c.g,c.b); C=(1-c.r-K)/(1-K); M=(1-c.g-K)/(1-K); Y=(1-c.b-K)/(1-K)
        return f"cmyk({round_int(C*100)}, {round_int(M*100)}, {round_int(Y*100)}, {round_int(K*100)})"
    if typ=='name': return color_name(c)
    return c.hex()

def color_name(c):
    hx = Color(*[x/255 for x in c.rgb8()],1).hex()
    if hx in HEX_TO_NAME: return HEX_TO_NAME[hx]
    # nearest in Lab (CIE76)
    L,A,B=rgb_to_lab(c); best=None; bd=1e99
    for n,h in CSS.items():
        cc=parse_color(h); l,a,b=rgb_to_lab(cc); d=(L-l)**2+(A-a)**2+(B-b)**2
        if d<bd: bd=d; best=n
    return best or hx

def default_out(c): return fmt_hsl(c, spaces=False)

def read_colors(args, start=0):
    colors=[]; errors=[]; had_stdin=False
    tokens=args[start:]
    if not tokens:
        tokens=[line.rstrip('\n') for line in sys.stdin]
    for t in tokens:
        if t == '-':
            line=sys.stdin.readline()
            if line=='': line=''
            t=line.rstrip('\n')
        if t == 'pick':
            errors.append("No color picker found") ; continue
        try: colors.append(parse_color(t))
        except Exception:
            errors.append(f"Could not parse color '{t}'")
    return colors, errors

def print_errors(errors):
    for e in errors: print(f"[pastel error]: {e}", file=sys.stderr)

def transform_colors(args, func, color_start=0):
    colors,errs=read_colors(args, color_start); outs=[]
    for c in colors: outs.append(default_out(func(c)))
    for o in outs: print(o, flush=True)
    print_errors(errs)
    return 1 if errs else 0

def interpolate(c1,c2,t,space):
    a=c1.a*(1-t)+c2.a*t; sp=space.lower()
    if sp=='rgb': return Color(c1.r*(1-t)+c2.r*t, c1.g*(1-t)+c2.g*t, c1.b*(1-t)+c2.b*t, a).clipped()
    if sp=='hsl':
        h1,s1,l1=rgb_to_hsl(c1); h2,s2,l2=rgb_to_hsl(c2); dh=((h2-h1+180)%360)-180
        return hsl_to_rgb(h1+dh*t, s1*(1-t)+s2*t, l1*(1-t)+l2*t, a)
    if sp=='lch':
        L1,A1,B1=rgb_to_lab(c1); L1,C1,h1=lab_to_lch(L1,A1,B1); L2,A2,B2=rgb_to_lab(c2); L2,C2,h2=lab_to_lch(L2,A2,B2); dh=((h2-h1+180)%360)-180
        L=L1*(1-t)+L2*t; C=C1*(1-t)+C2*t; h=h1+dh*t; L,A,B=lch_to_lab(L,C,h); return lab_to_rgb(L,A,B,a)
    if sp=='oklab':
        p1=rgb_to_oklab(c1); p2=rgb_to_oklab(c2); return oklab_to_rgb(*(p1[i]*(1-t)+p2[i]*t for i in range(3)), alpha=a)
