    p1=rgb_to_lab(c1); p2=rgb_to_lab(c2); return lab_to_rgb(*(p1[i]*(1-t)+p2[i]*t for i in range(3)), alpha=a)

def ansi_seq(c, bg=False, mode='24bit'):
    r,g,b=c.rgb8(); base=48 if bg else 38
    if mode=='8bit': return f"\x1b[{base};5;{nearest_ansi8(c)}m"
    return f"\x1b[{base};2;{r};{g};{b}m"

def sort_key(c, order):
    if order=='brightness': return brightness(c)
    if order=='luminance': return rel_luminance(c)
    if order=='chroma':
        L,A,B=rgb_to_lab(c); return math.hypot(A,B)
    if order=='random': return random.random()
    return rgb_to_hsl(c)[0]

ROOT_HELP = '''A command-line tool to generate, analyze, convert and manipulate colors

Usage: executable [OPTIONS] <COMMAND>

Commands:
