def generic_help(cmd):
    desc={
        'color':'Show and display some information about the given color(s).', 'format':'Convert the given color(s) to a specific format.',
        'colorcheck':'Check if your terminal emulator supports 24-bit colors.', 'gray':'Create a gray tone from a given lightness value.',
        'list':'Show a list of available color names', 'paint':'Print colored text using ANSI escape sequences',
        'random':'Generate a list of random colors.', 'textcolor':'Return a readable foreground text color (either black or white) for a given background color.',
        'to-gray':'Completely desaturate the given color while preserving the luminance.', 'mix':'Create new colors by interpolating between two colors in the given colorspace.',
        'gradient':'Generate a sequence of colors that interpolates between the specified colors.', 'sort-by':'Sort a list of colors by the given property.',
        'set':'Set the given property to a specific value', 'colorblind':'Convert the given color to how it would look to a person with protanopia, deuteranopia, or tritanopia ',
        'complement':'Compute the complementary color by rotating the HSL hue channel by 180°.', 'lighten':'Lighten a color by adding a certain amount to the lightness channel.',
        'darken':'Darken a color by subtracting a certain amount from the lightness channel.', 'saturate':'Increase the saturation of a color by adding a certain amount to the HSL saturation channel.',
        'desaturate':'Decrease the saturation of a color by subtracting a certain amount from the HSL saturation channel.', 'rotate':'Rotate the HSL hue channel of a color by the specified angle (in degrees).',
        'distinct':'Generate a set of visually distinct colors by maximizing the perceived color difference between pairs of colors.', 'pick':'Print a spectrum of colors to choose from.'}
    usage={
        'format':'executable format [type] [color]...', 'color':'executable color [color]...', 'colorcheck':'executable colorcheck', 'gray':'executable gray <lightness>',
        'list':'executable list [OPTIONS]', 'paint':'executable paint [OPTIONS] <color> [text]...', 'random':'executable random [OPTIONS]', 'mix':'executable mix [OPTIONS] <color> [color]...',
        'gradient':'executable gradient [OPTIONS] <color>...', 'sort-by':'executable sort-by [OPTIONS] [sort-order] [color]...', 'set':'executable set <property> <value> [color]...',
        'colorblind':'executable colorblind <type> [color]...', 'distinct':'executable distinct [OPTIONS] [count] [color]...', 'pick':'executable pick [count]'}
    if cmd in ['complement','lighten','darken','saturate','desaturate','rotate','textcolor','to-gray']:
        usage[cmd]=f"executable {cmd} " + ({'lighten':'<amount> ','darken':'<amount> ','saturate':'<amount> ','desaturate':'<amount> ','rotate':'<degrees> '}.get(cmd,'')) + '[color]...'
    print(desc.get(cmd,'')+"\n")
    print('Usage: '+usage.get(cmd,f'executable {cmd}')+'\n')
    print('Options:\n  -h, --help  Print help')

# Machado et al. full dichromacy matrices, enough to match the visible behavior closely.
CB_MATS={
 'prot':((0.152286,1.052583,-0.204868),(0.114503,0.786281,0.099216),(-0.003882,-0.048116,1.051998)),
 'deuter':((0.367322,0.860646,-0.227968),(0.280085,0.672501,0.047413),(-0.011820,0.042940,0.968881)),
 'trit':((1.255528,-0.076749,-0.178779),(-0.078411,0.930809,0.147602),(0.004733,0.691367,0.303900)),
}
def colorblind(c, typ):
    m=CB_MATS[typ]; r,g,b=c.r,c.g,c.b
    return Color(m[0][0]*r+m[0][1]*g+m[0][2]*b, m[1][0]*r+m[1][1]*g+m[1][2]*b, m[2][0]*r+m[2][1]*g+m[2][2]*b, c.a).clipped()

def main(argv):
    args=list(argv[1:]); mode='auto'
    i=0; rest=[]
    while i < len(args):
        a=args[i]
        if a in ('--help','-h'):
            print(ROOT_HELP); return 0
        if a in ('--version','-V'):
            print(VERSION); return 0
        if a in ('-f','--force-color'):
            mode='24bit'; i+=1; continue
        if a in ('-m','--color-mode','--mode'):
            if i+1<len(args): mode=args[i+1]; i+=2; continue
