        print(ROOT_HELP); return 0
    cmd=rest[0]; ca=rest[1:]
    if cmd=='help':
        if ca: generic_help(ca[0])
        else: print(ROOT_HELP)
        return 0
    if '--help' in ca or '-h' in ca:
        generic_help(cmd); return 0
    try:
        if cmd=='format':
            typ='hex'; start=0
            if ca and ca[0] in FORMATS: typ=ca[0]; start=1
            elif ca and not ca[0].startswith('-') and ca[0] not in FORMATS and len(ca)>1:
                print(f"error: invalid value '{ca[0]}' for '[type]'", file=sys.stderr); return 2
            colors,errs=read_colors(ca,start)
            no_nl=typ.endswith('escapecode')
            for c in colors:
                end='' if no_nl else '\n'; print(format_color(c,typ), end=end, flush=True)
            print_errors(errs); return 1 if errs else 0
        if cmd=='color':
            colors,errs=read_colors(ca,0)
            for c in colors: print(default_out(c), flush=True)
            print_errors(errs); return 1 if errs else 0
        if cmd in ('lighten','darken','saturate','desaturate'):
            if not ca: return 2
            amt=float(ca[0])
            def f(c):
                h,s,l=rgb_to_hsl(c)
                if cmd=='lighten': l=clamp(l+amt)
                elif cmd=='darken': l=clamp(l-amt)
                elif cmd=='saturate': s=clamp(s+amt)
                else: s=clamp(s-amt)
                return hsl_to_rgb(h,s,l,c.a)
            return transform_colors(ca,f,1)
        if cmd in ('rotate','complement'):
            deg=180.0 if cmd=='complement' else float(ca[0]); start=0 if cmd=='complement' else 1
