            v=clamp(float(ca[0])); print(default_out(Color(v,v,v))); return 0
        if cmd=='textcolor':
            def f(c): return Color(0,0,0,c.a) if rel_luminance(c)>0.17913 else Color(1,1,1,c.a)
            return transform_colors(ca,f,0)
        if cmd=='to-gray':
            def f(c):
                y=rel_luminance(c); g=linear_to_srgb(y); h,s,l=rgb_to_hsl(c); return hsl_to_rgb(h,0,g,c.a)
            return transform_colors(ca,f,0)
        if cmd=='mix':
            sp='Lab'; frac=0.5; rem=[]; j=0
            while j<len(ca):
                if ca[j] in ('-s','--colorspace') and j+1<len(ca): sp=ca[j+1]; j+=2
                elif ca[j].startswith('--colorspace='): sp=ca[j].split('=',1)[1]; j+=1
                elif ca[j] in ('-f','--fraction') and j+1<len(ca): frac=float(ca[j+1]); j+=2
                elif ca[j].startswith('--fraction='): frac=float(ca[j].split('=',1)[1]); j+=1
                else: rem.append(ca[j]); j+=1
