            print_errors(errs); return 1 if errs else 0
        if cmd=='random':
            strat='vivid'; n=10; j=0
            while j<len(ca):
                if ca[j] in ('-n','--number') and j+1<len(ca): n=int(ca[j+1]); j+=2
                elif ca[j].startswith('--number='): n=int(ca[j].split('=',1)[1]); j+=1
                elif ca[j] in ('-s','--strategy') and j+1<len(ca): strat=ca[j+1]; j+=2
                elif ca[j].startswith('--strategy='): strat=ca[j].split('=',1)[1]; j+=1
                else: j+=1
            for _ in range(n):
